                ref_part, weight_str = raw_ref.rsplit(":", 1)
                try:
                    edge_weight = float(weight_str)
                    raw_ref = ref_part
                except ValueError:
                    pass
            parts = raw_ref.split("/", 1)
            if len(parts) != 2:
                continue
            n_cat, n_id = parts
            if n_id in direct_ids:
                continue
